import { SystemAuditLogEntity } from '../interfaces/system-audit-logs-entity.interface';

/**
 * Input type for creating an audit log.
 * 
 * We omit the fields that are generated by the database or derived by the 
 * repository (`id`, `createdAt`, `actorName`, `commandCenterName`). 
 * The repository will automatically resolve `actorName` from `actorId` and 
 * `commandCenterName` from `commandCenterId`.
 */
export type CreateAuditLogInput = Omit<
  SystemAuditLogEntity,
  'id' | 'createdAt' | 'actorName' | 'commandCenterName'
> & {
  id?: string;
  createdAt?: Date;
};